Nuvens contaminam os píxeis e introduzem erros na classificação. Usamos o algoritmo simpleCloudScore do GEE com um limiar de 3%:var cloud_thresh = 0.03;

var cloudfunction = function(image) {
  var cloudScore = ee.Algorithms.Landsat.simpleCloudScore(image);
  var quality = cloudScore.select('cloud');
  var cloud1 = quality.gt(cloud_thresh);
  var cloudmask = image.mask().and(cloud1.not());
  return image.mask(cloudmask);
};

var L8_B_2019N = L8_Collection.map(cloudfunction);
var median_L8 = L8_B_2019N.median();

A função .median() cria uma imagem composta usando o valor mediano de cada píxel ao longo de todos os meses — uma técnica eficaz para suprimir ruído residual de nuvens.

NDVI = \frac{NIR - RED}{NIR + RED}var NDVI = median_L8.expression(
    '(NIR - RED) / (NIR + RED)', {
      'NIR': median_L8.select('B5'),
      'RED': median_L8.select('B4'),
    }).rename('NDVI');

EVI2 = 2.5 \times \frac{NIR - RED}{NIR + 2.4 \times RED + 1}var EVI2 = median_L8.expression(
  '2.5 * ((NIR - RED) / (NIR + (2.4 * RED) + 1))', {
    'NIR': median_L8.select('B5'),
    'RED': median_L8.select('B4'),
  }).rename('EVI2');

SAVI = \frac{(NIR - RED)}{(NIR + RED + L)} \times (1 + L), \quad L = 0.5var SAVI = median_L8.expression(
  '((NIR - RED) / (NIR + RED + L)) * (1 + L)', {
    'NIR': median_L8.select('B5'),
    'RED': median_L8.select('B4'),
    'L': 0.5
}).rename('SAVI');

NDWI = \frac{GREEN - NIR}{GREEN + NIR}var NDWI = median_L8.expression(
  '(G - NIR) / (G + NIR)', {
    'G': median_L8.select('B3'),
    'NIR': median_L8.select('B5')
  }).rename('NDWI');

Para além dos índices espectrais, o modelo incorpora elevação e declive derivados do ALOS DEM (30 m), o que melhora a separação entre classes como floresta de encosta e solo exposto:var alos = ee.Image("JAXA/ALOS/AW3D30/V2_2");

var addIndices = function(image) {
  var EVI2 = image.expression(
    '2.5 * ((NIR - RED) / (NIR + (2.4 * RED) + 1))',
    {'NIR': image.select('B5'), 'RED': image.select('B4')}
  ).rename('EVI2');
  var NDVI = image.expression(
    '(NIR - RED) / (NIR + RED)',
    {'NIR': image.select('B5'), 'RED': image.select('B4')}
  ).rename('NDVI');
  return image.addBands(EVI2).addBands(NDVI);
};

var composite = addIndices(median_L8.clip(banhine));
var elev  = alos.select('AVE_DSM').divide(2000).rename('elev');
var slope = ee.Terrain.slope(alos.select('AVE_DSM')).divide(30).rename('slope');
var composite = composite.addBands(elev).addBands(slope);

Porquê normalizar? Dividir a elevação por 2000 e o declive por 30 coloca ambas as variáveis numa escala comparável às bandas espectrais (0–1), evitando que dominem o classificador.

As amostras de campo (gcp) foram recolhidas para quatro classes: floresta, plano de água, solo exposto e pastagem/savana. A divisão aleatória garante uma avaliação independente:var gcp = greenForest.merge(waterBody).merge(soil).merge(grass);
var gcp = gcp.randomColumn();

// 40% para treino, 30% para validação
var trainingGCP   = gcp.filter(ee.Filter.lt('random', 0.4));
var validationGCP = gcp.filter(ee.Filter.gte('random', 0.7));

var training = composite.sampleRegions({
  collection: trainingGCP,
  properties: ['properties'],
  scale: 10,
  tileScale: 16
});

O algoritmo CART (Classification and Regression Trees) constrói uma árvore de decisão binária que divide os dados com base nos índices espectrais e topográficos:var classifier = ee.Classifier.smileCart(10)
    .train({
      features: training,
      classProperty: 'properties',
      inputProperties: composite.bandNames()
    });

var classified = composite.classify(classifier);

A matriz de confusão é a forma padrão de avaliar a qualidade de uma classificação supervisionada:var test = classified.sampleRegions({
  collection: validationGCP,
  properties: ['properties'],
  scale: 10,
  tileScale: 16
});

var testConfusionMatrix = test.errorMatrix('properties', 'classification');
print('Confusion Matrix', testConfusionMatrix);
print('Test Accuracy', testConfusionMatrix.accuracy());

Para encontrar o número óptimo de árvores de decisão, testamos valores entre 10 e 120 e representamos graficamente a precisão de validação:var numTreesList = ee.List.sequence(10, 120, 10);

var accuracies = numTreesList.map(function(numTrees){
  var classifier = ee.Classifier.smileCart(numTrees)
    .train({
      features: training,
      classProperty: 'properties',
      inputProperties: composite.bandNames()
    });
  return test
    .classify(classifier)
    .errorMatrix('properties', 'classification')
    .accuracy();
});

var chart = ui.Chart.array.values({
  array: ee.Array(accuracies),
  axis: 0,
  xLabels: numTreesList
}).setOptions({
  title: 'Hyperparameter Tuning — numberOfTrees',
  vAxis: {title: 'Validation Accuracy'},
  hAxis: {title: 'Number of Trees', gridlines: {count: 15}}
});

print(chart);

O gráfico gerado pelo GEE permite identificar visualmente o ponto de diminishing returns — o número de árvores a partir do qual a precisão se estabiliza.



Figure 1:Gráfico de optimização do número de árvores (numberOfTrees) no modelo CART, mostrando a evolução da precisão com o aumento de estimadores.

O formulário de alerta foi organizado em módulos de identificação, localização, choque, movimento, necessidades, pressão comunitária, cobertura, acesso, confiança e resultados calculados.

O formulário comunitário e a grelha de observação recuperam do alerta seleccionado:

comunidade ou local de chegada;

local de origem ou do choque;

tipo de choque;

data aproximada;

outros campos úteis para verificação.

Esta arquitectura reduz repetição, melhora a rastreabilidade e permite comparar a informação inicial com a evidência recolhida posteriormente.

Uma selecção administrativa pode guardar mz0112, mas mostrar Mueda. A referência ${arrival_districts} devolve o código interno; jr:choice-name() devolve o label.

A regra adoptada foi:

usar códigos internos para integração e análise;

usar labels quando a legibilidade humana é necessária;

evitar dados pessoais no identificador;

manter sempre um sufixo aleatório para prevenir duplicados.

Exemplo:pulldata(
  'alerts',
  'community_site',
  'name',
  ${alert_id_ref}
)

O primeiro argumento é o nome do ficheiro sem .csv. Os dados recuperados podem formar uma pergunta dinâmica:Did you or your household arrive in ${alert_community_site}
from ${alert_origin_location}
following ${alert_shock_event_en}
on or around ${alert_shock_date_en}?

O desenho bilingue exige colunas próprias para textos dinâmicos, como shock_event_en, shock_event_pt, shock_date_en e shock_date_pt.

A grelha de observação incluiu um repeat para pontos de água. O número de repetições é definido pela quantidade de pontos efectivamente observados:type: begin_repeat
name: water_point_loop
relevant:
${water_points_observed} = 'yes'
and ${water_points_assessed_count} > 0

repeat_count:
${water_points_assessed_count}

Dentro do repeat, o identificador sequencial pode ser criado com:concat(
  'WP',
  if(
    position(..) < 10,
    concat('0', position(..)),
    position(..)
  )
)

Resultados:WP01
WP02
WP03

Um erro do Enketo mostrou que uma referência como ../water_point_id podia falhar quando o nó esperado não existia no contexto em que o label ou note era avaliado:FormLogicError: Could not evaluate: ../water_point_id

A abordagem segura foi testar primeiro o repeat sem notes dinâmicos, confirmar repeat_count, calculation e a posição de end_repeat, e só depois adicionar elementos de apresentação.

Regras práticas:

usar a coluna repeat_count, não calculation;

manter end_repeat antes do end_group externo;

evitar referências ambíguas entre níveis;

testar o repeat isoladamente;

não tornar GPS obrigatório quando a instrução diz “se seguro e viável”.

As listas internas devem existir numa folha chamada exactamente choices, com list_name, name e labels. Os valores em type precisam de coincidir exactamente com list_name.

No entanto, quando perguntas ou grupos dependem do alerta, a ausência temporária das opções pode ser causada pela lógica de relevância e não pela folha choices.

Por isso, o diagnóstico deve seguir esta ordem:

confirmar o list_name;

confirmar que a folha se chama choices;

confirmar que o formulário implementado contém a versão mais recente;

verificar choice_filter e relevant;

seleccionar os campos dos quais a lista depende;

testar novamente no Enketo e KoboCollect.

Um filtro construído para a lista serious_problem foi aplicado por engano a uma pergunta que utilizava priority_support. Embora a expressão fosse tecnicamente válida, as opções eram ocultadas de forma incorrecta. A regra adoptada foi verificar sempre, em conjunto:

o list_name declarado em type;

as colunas existentes nessa lista na folha choices;

os nomes usados no choice_filter;

pelo menos um cenário em que cada opção deve aparecer.

Quando a lista de apoio já contém todas as opções válidas, o filtro deve ficar vazio.

Uma lista continha a opção one_observed, enquanto a restrição procurava none_observed. Noutra lista, existia um campo “Other, specify”, mas não existia a opção other. Estes casos confirmam que a revisão deve comparar sistematicamente:

nomes usados em selected() com os name da folha choices;

opções other com os respectivos campos de especificação;

labels em inglês e português;

texto da pergunta com o sector correcto;

required, relevant e constraint como uma única regra lógica.

Uma tradução vazia não quebra necessariamente o XForm, mas quebra a experiência bilingue. Por isso, a completude linguística deve fazer parte do controlo de qualidade antes da implementação.

A utilização de CSV externo introduz uma etapa de manutenção. Novos alertas só aparecem depois de actualizar, carregar e sincronizar o ficheiro.

Outras limitações:

versões diferentes do CSV entre dispositivos;

necessidade de conectividade para actualização;

regras de pontuação que exigem revisão periódica;

diferenças de comportamento entre Enketo e KoboCollect;

complexidade adicional em repeats e referências entre níveis;

possibilidade de o contexto mudar entre o alerta e a entrevista.

Quando operacionalmente adequado, integrações dinâmicas entre projectos podem reduzir a manutenção manual. Ainda assim, o CSV continua útil para controlar a lista activa e preparar labels legíveis.

O ponto de partida foi a criação de um manual do básico ao avançado sobre desenvolvimento de plugins QGIS com Python. O documento precisava de ensinar não apenas a estrutura mínima de um plugin, mas também aspectos mais avançados, incluindo:

classFactory(), initGui(), run() e unload();

menus, barras de ferramentas, QDialog e QDockWidget;

camadas vectoriais, geometrias e transformação de sistemas de referência;

tarefas em segundo plano com QgsTask;

processamento em lote e integração segura com GDAL;

ferramentas de mapa e snapping;

pedidos de rede com QgsNetworkAccessManager;

compatibilidade QGIS 3/4 e Qt 5/6;

testes, empacotamento, CI/CD e publicação.

Para tornar o conteúdo concreto, foram utilizados dois estudos de caso reais:

GPX Batch Converter, orientado à conversão em lote, execução em segundo plano, cancelamento, formatos GIS e relatórios;

GeoClick Capture, orientado à captura de pontos, snapping, transformação de coordenadas, sessões, geocodificação e painéis laterais.

A primeira versão do manual foi produzida em Markdown, convertida para DOCX e PDF e publicada como asset de uma GitHub Release. Esta solução funcionava, mas ainda apresentava uma limitação importante: o conteúdo não era facilmente navegável na Web.

Um manual técnico extenso beneficia de uma estrutura de livro, e não apenas de uma página longa. O 

Quarto permite combinar vários capítulos num único projecto e produzir HTML, PDF, Word, EPUB e outros formatos a partir de fontes textuais. A versão HTML de um Quarto Book inclui funcionalidades particularmente úteis para documentação técnica:

índice lateral persistente;

pesquisa em todo o livro;

navegação anterior/seguinte;

links directos para secções;

numeração de capítulos;

referências cruzadas;

realce e cópia de código;

tema claro e escuro;

desenho responsivo para computador e telemóvel.

A decisão mais importante não foi apenas adoptar Quarto, mas fazê-lo sem criar uma segunda fonte de verdade. O conteúdo principal permaneceu em:manual/manual.md

Os ficheiros .qmd usados pelo Quarto passaram a ser gerados automaticamente.

O manual original já estava dividido internamente em seis partes. O script prepare_quarto.py utiliza esses títulos para gerar os capítulos Quarto.

A lógica central é:

ler manual/manual.md;

remover o front matter e marcadores exclusivos de impressão;

identificar títulos como # Parte I - Fundamentos;

separar prefácio, seis partes e apêndices;

ajustar os níveis dos títulos;

gravar os ficheiros .qmd dentro de chapters/.

Exemplo simplificado:PART_FILES = {
    "I": "01-fundamentos.qmd",
    "II": "02-primeiro-plugin.qmd",
    "III": "03-desenvolvimento-intermedio.qmd",
    "IV": "04-desenvolvimento-avancado.qmd",
    "V": "05-estudos-de-caso.qmd",
    "VI": "06-projecto-pratico.qmd",
}

part_match = re.match(r"^# Parte ([IVX]+)\s*-\s*(.+)$", line)

Esta abordagem evita editar manualmente vários capítulos sempre que o conteúdo muda. O repositório mantém apenas uma fonte editorial, enquanto o Quarto recebe uma estrutura optimizada para leitura online.

O pipeline não se limita a executar quarto render. Foram adicionadas verificações automáticas para detectar problemas antes da publicação:test -s _book/index.html
test -s _book/search.json
grep -q 'Jubílio Filiano Maússe' _book/index.html

Também é verificado que a grafia incorrecta do apelido não aparece no livro:if grep -R 'Jubílio Filiano Mausse' _book --include='*.html'; then
  echo "The rendered book contains the unaccented family name"
  exit 1
fi

Outras validações do repositório incluem:

compilação dos exemplos Python;

existência dos ficheiros obrigatórios;

formato semântico da versão;

ausência de __pycache__ e .pyc versionados;

construção de PDF e DOCX;

extracção do texto do PDF para confirmar os acentos;

hashes SHA-256 dos assets da release.

Manter PDF e DOCX dentro da árvore principal criava risco de divergência entre fonte e documento publicado. A solução foi:

ignorar os ficheiros gerados no Git;

produzi-los no workflow;

publicá-los como assets de uma release versionada.

As releases incluem:

PDF;

versão editável em Word;

pacote-fonte;

hashes SHA-256.

O manual online oferece pesquisa e navegação; o PDF é adequado a leitura offline e impressão; o Word permite revisão e adaptação; o repositório permite estudar e executar os exemplos.

Ciência de dados geoespaciais aplicada à acção humanitária;

Avaliações multissectoriais e análise de risco;

Águas subterrâneas, WASH e segurança hídrica;

Sensoriamento remoto para monitorização ambiental;

Sistemas digitais de recolha e integração de dados;

Automatização, reprodutibilidade e ferramentas abertas para SIG.
